node'da yazdığım script bazen boş array dönüyo bazen de "Cannot read properties of undefined (reading 'map')" patlıyo. forEach içinde await kullanmam mı sorun? kodun tamamı bu

const axios = require("axios");
const fs = require("fs/promises");

const BASE = "https://api.ornek-magaza.local/v1";

async function urunleriGetir(kategoriId) {
  const res = await axios.get(`${BASE}/kategoriler/${kategoriId}/urunler`);
  return res.data.items;
}

async function stokGetir(urunId) {
  try {
    const res = await axios.get(`${BASE}/stok/${urunId}`);
    return res.data;
  } catch (e) {
    console.log("stok alinamadi", urunId);
  }
}

async function raporOlustur(kategoriler) {
  const rapor = [];
  kategoriler.forEach(async (k) => {
    const urunler = await urunleriGetir(k.id);
    const satirlar = urunler.map(async (u) => {
      const stok = await stokGetir(u.id);
      return { ad: u.ad, fiyat: u.fiyat, adet: stok.adet, depo: stok.depo };
    });
    rapor.push(...satirlar);
  });
  return rapor;
}

(async () => {
  const kategoriler = JSON.parse(await fs.readFile("kategoriler.json", "utf8"));
  const rapor = await raporOlustur(kategoriler);
  console.log(rapor.length, "satir");
  await fs.writeFile("rapor.json", JSON.stringify(rapor, null, 2));
})();

