column7:
at org.springframework.web.method.support.InvocableHandlerMethod.doInvoke(InvocableHandlerMethod.java:205)

@Service
public class SiparisService {
    @Autowired private MusteriRepository musteriRepo;
    @Autowired private KargoHesaplayici kargo;
    @Autowired private SiparisRepository siparisRepo;

    @Transactional
    public Siparis olustur(SiparisIstegi istek) {
        Musteri m = musteriRepo.findById(istek.getMusteriId()).get();
        Siparis s = new Siparis();
        s.setMusteri(m);
        s.setKalemler(istek.getKalemler());
        BigDecimal araToplam = istek.getKalemler().stream()
            .map(k -> k.getBirimFiyat().multiply(BigDecimal.valueOf(k.getAdet())))
            .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal kargoUcreti = kargo.ucretHesapla(m, araToplam);
        s.setToplam(araToplam.add(kargoUcreti));
        return siparisRepo.save(s);
    }
}

public BigDecimal ucretHesapla(Musteri m, BigDecimal tutar) {
    if (tutar.compareTo(new BigDecimal("750")) >= 0) return BigDecimal.ZERO;
    String sehir = m.getTeslimatAdresi().getSehir();
    return sehir.equals("İstanbul") ? new BigDecimal("39.90") : new BigDecimal("59.90");
}

