const ozet = siparisler
  .filter(s => s.durum !== "iptal")
  .reduce((acc, s) => {
    const ay = s.tarih.slice(0, 7);
    acc[ay] = acc[ay] || { adet: 0, ciro: 0 };
    acc[ay].adet += 1;
    acc[ay].ciro += s.kalemler.reduce((t, k) => t + k.fiyat * k.miktar, 0);
    return acc;
  }, {});

const sirali = Object.entries(ozet).sort(([a], [b]) => a.localeCompare(b));

arduino kodu derlenmiyo hata bu, step motor sürücüsü A4988 için yazdım

#define STEP_PIN 3
#define DIR_PIN 4
int hiz = 800

void setup() {
  pinMode(STEP_PIN, OUTPUT);
  pinMode(DIR_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  if (Serial.available()) {
    char c = Serial.read();
    if (c == "r") digitalWrite(DIR_PIN, HIGH);
    if (c == "l") digitalWrite(DIR_PIN, LOW);
  }
  adimAt(200);
}

void adimAt(int adet) {
  for (int i = 0; i < adet; i++) {
    digitalWrite(STEP_PIN, HIGH);
    delayMicroseconds(hiz);
    digitalWrite(STEP_PIN, LOW);
    delayMicroseconds(hiz);
  }

