winforms uygulamam var stok takip, kaydet butonuna basınca bazen şu hatayı veriyo bazen de program donuyo. kod aşağıda neleri yanlış yapmışım, sql injection da var mı

System.InvalidOperationException: There is already an open DataReader associated with this Connection which must be closed first.
   at System.Data.SqlClient.SqlCommand.ValidateCommand(Boolean isAsync, String method)
   at System.Data.SqlClient.SqlCommand.ExecuteNonQuery()
   at StokTakip.FrmUrun.btnKaydet_Click(Object sender, EventArgs e) in FrmUrun.cs:line 47

static SqlConnection baglanti = new SqlConnection(Ayarlar.BaglantiCumlesi);

private void btnKaydet_Click(object sender, EventArgs e)
{
    if (baglanti.State == ConnectionState.Closed) baglanti.Open();

    SqlCommand kontrol = new SqlCommand("SELECT * FROM Urunler WHERE Barkod = '" + txtBarkod.Text + "'", baglanti);
    SqlDataReader dr = kontrol.ExecuteReader();
    if (dr.Read())
    {
        int mevcut = Convert.ToInt32(dr["Adet"]);
        SqlCommand guncelle = new SqlCommand("UPDATE Urunler SET Adet = " + (mevcut + int.Parse(txtAdet.Text)) + " WHERE Barkod = '" + txtBarkod.Text + "'", baglanti);
        guncelle.ExecuteNonQuery();
    }
    else
    {
        SqlCommand ekle = new SqlCommand("INSERT INTO Urunler (Barkod, Ad, Adet, Fiyat) VALUES ('" + txtBarkod.Text + "','" + txtAd.Text + "'," + txtAdet.Text + "," + txtFiyat.Text + ")", baglanti);
        ekle.ExecuteNonQuery();
    }
    Listele();
    MessageBox.Show("Kaydedildi");
}

